package com.mohymods.kingdomsmp.profession;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.block.*;
/** Read-only loaded two-floor circulation and functional-zone inspection; existing OP2attestation remains required. */
public final class LayeredInteriorInspection {
 public static final String QUEST="kingdom_smp:builder/m04";
 private LayeredInteriorInspection(){}
 private record Station(BlockPos pos,String type,Set<BlockPos> access){}
 static boolean spaced(BlockPos a,BlockPos b){return Math.abs(a.getX()-b.getX())>=3||Math.abs(a.getZ()-b.getZ())>=3;}
 static boolean levels(int a,int b){return b-a>=3&&b-a<=8;}
 private static boolean inside(BlockPos p,BlockPos from,BlockPos to){return p.getX()>=from.getX()&&p.getX()<=to.getX()&&p.getY()>=from.getY()&&p.getY()<=to.getY()&&p.getZ()>=from.getZ()&&p.getZ()<=to.getZ();}
 private static boolean walkable(ServerLevel level,BlockPos feet){var below=feet.below();var state=level.getBlockState(below);return level.getBlockState(feet).getFluidState().isEmpty()&&level.getBlockState(feet.above()).getFluidState().isEmpty()&&BuilderInspectionGeometry.clear(level,feet)&&(state.isFaceSturdy(level,below,Direction.UP)||state.getBlock() instanceof StairBlock||state.getBlock() instanceof SlabBlock);}
 private static Set<BlockPos> connected(Set<BlockPos> paths,BlockPos start){var result=new HashSet<BlockPos>();var queue=new ArrayDeque<BlockPos>();result.add(start);queue.add(start);while(!queue.isEmpty()){var p=queue.removeFirst();for(var side:Direction.Plane.HORIZONTAL)for(int dy=-1;dy<=1;dy++){var next=p.relative(side).offset(0,dy,0);if(paths.contains(next)&&result.add(next))queue.addLast(next);}}return result;}
 private static boolean select(List<Station> candidates,Set<BlockPos> reachable,int index,List<Station> chosen,int[] budget){if(chosen.size()==4)return chosen.stream().map(Station::type).distinct().count()>=2;for(int n=index;n<candidates.size();n++){if(--budget[0]<0)return false;var station=candidates.get(n);if(station.access().stream().noneMatch(reachable::contains)||chosen.stream().anyMatch(old->!spaced(station.pos(),old.pos())))continue;chosen.add(station);if(select(candidates,reachable,n+1,chosen,budget))return true;chosen.removeLast();}return false;}
 static void requirePlayerProject(ServerPlayer p,BlockPos from,BlockPos to){var box=new net.minecraft.world.phys.AABB(from.getX(),from.getY(),from.getZ(),to.getX()+1,to.getY()+1,to.getZ()+1);for(var project:com.mohymods.kingdomsmp.building.ConstructionService.store(p.server).projects())if(project.origin()!=null&&box.intersects(com.mohymods.kingdomsmp.building.ConstructionService.bounds(project)))throw new IllegalStateException("Inspect a separate player-built project outside registered kingdom buildings and reservations; Aldric reward structures do not count");var hut=com.mohymods.kingdomsmp.persistence.BuilderHutSavedData.get(p.server).hut().orElse(null);if(hut!=null){var b=com.mohymods.kingdomsmp.building.BuilderHutBlueprint.create();var o=hut.origin();if(box.intersects(new net.minecraft.world.phys.AABB(o.getX(),o.getY()-4,o.getZ(),o.getX()+b.width(hut.rotation()),o.getY()+com.mohymods.kingdomsmp.building.BuilderHutBlueprint.HEIGHT,o.getZ()+b.depth(hut.rotation()))))throw new IllegalStateException("The starting Hut cannot supply player-authored inspection credit");}}
 public static String validate(ServerPlayer p,BlockPos center){var level=p.serverLevel();var from=center.offset(-8,-3,-8);var to=center.offset(8,10,8);requirePlayerProject(p,from,to);var pathFrom=center.offset(-8,-2,-8);var pathTo=center.offset(8,9,8);var paths=new HashSet<BlockPos>();var floors=new TreeMap<Integer,List<Station>>();int stairs=0;
  for(var cursor:BlockPos.betweenClosed(from,to)){var pos=cursor.immutable();if(inside(pos,pathFrom,pathTo)&&walkable(level,pos))paths.add(pos);if(level.getBlockState(pos).getBlock() instanceof StairBlock)stairs++;if(pos.getY()<center.getY()-2||pos.getY()>center.getY()+6)continue;var type=BuilderInspectionGeometry.station(level.getBlockState(pos));if(type==null||!BuilderInspectionGeometry.roof(level,pos))continue;var access=new HashSet<BlockPos>();for(var side:Direction.Plane.HORIZONTAL){var feet=pos.relative(side);if(inside(feet,pathFrom,pathTo)&&walkable(level,feet))access.add(feet);}if(access.isEmpty())continue;var candidates=floors.computeIfAbsent(pos.getY(),y->new ArrayList<>());if(candidates.size()<24)candidates.add(new Station(pos,type,Set.copyOf(access)));}
  if(stairs<1)throw new IllegalStateException("Maintain a real internal stair connection between the furnished floors");
  int[] budget={16384};var remaining=new HashSet<>(paths);while(!remaining.isEmpty()){var reach=connected(paths,remaining.iterator().next());remaining.removeAll(reach);if(reach.size()<8)continue;for(var lower:floors.entrySet())for(var upper:floors.entrySet()){if(!levels(lower.getKey(),upper.getKey())||lower.getValue().size()<4||upper.getValue().size()<4)continue;if(select(lower.getValue(),reach,0,new ArrayList<>(),budget)&&select(upper.getValue(),reach,0,new ArrayList<>(),budget))return "interiorFloors=2,zones=8,circulation=connected,lower="+lower.getKey()+",upper="+upper.getKey();if(budget[0]<0)throw new IllegalStateException("Interior inspection budget exceeded; review a smaller uncluttered room");}}
  throw new IllegalStateException("Maintain2roofed usable floors3–8blocks apart, with4spaced functional zones of at least2purposes on each floor and a clear supported internal stair route joining all8areas. Ordinary workstations, storage, study and rest qualify; no service unlock is granted");
 }
}
